1	import { useEffect, useState } from 'react'
2	import { LogoMark } from '../icons'
3	import { trpc } from '../trpc'
4	import { useWorkspace, type DriveState } from '../lib/workspace'
5	import type { ProjectNavApi } from '../lib/use-project-nav'
6	import { Titlebar } from './Titlebar'
7	import { Sidebar } from './Sidebar'
8	import { Inspector } from './Inspector'
9	import { StatusBar } from './StatusBar'
10	import { Workspace } from './Workspace'
11	import { NewFeatureForm } from './NewFeatureForm'
12	import { CommandPalette } from './CommandPalette'
13	import { SettingsOverlay } from './SettingsOverlay'
14	
15	/**
16	 * The runcastle IDE shell for a single project (app-redesign, multi-project #45).
17	 * A title bar, a triage features rail, a single workspace bound to the selected
18	 * feature (or the new-feature form), the inspector rail, and a status bar. ⌘K
19	 * opens the command palette. Everything here is scoped to `projectId`; the outer
20	 * shell picks which project (or the portfolio home) is showing. The active test
21	 * drive (at most one globally) is shell state, shared by the workspace and status
22	 * bar.
23	 */
24	export function ProjectShell({ projectId, nav }: { projectId: string; nav: ProjectNavApi }) {
25	  const ws = useWorkspace(projectId)
26	  const { selectedFeatureId, select, setCmdk } = ws
27	  const [driving, setDriving] = useState<DriveState | null>(null)
28	  const list = trpc.feature.list.useQuery({ projectId }, { refetchInterval: 1500 })
29	
30	  // Land on a feature: select the first one once, if nothing is selected yet.
31	  useEffect(() => {
32	    if (!selectedFeatureId && list.data && list.data.length > 0) select(list.data[0].id)
33	  }, [selectedFeatureId, list.data, select])
34	
35	  // Global ⌘K / Ctrl-K → command palette.
36	  useEffect(() => {
37	    const onKey = (e: KeyboardEvent) => {
38	      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
39	        e.preventDefault()
40	        setCmdk(true)
41	      }
42	    }
43	    window.addEventListener('keydown', onKey)
44	    return () => window.removeEventListener('keydown', onKey)
45	  }, [setCmdk])
46	
47	  const showInspector = !ws.inspectorCollapsed && !!ws.selectedFeatureId && !ws.creating
48	
49	  return (
50	    <div className={`shell${ws.inspectorCollapsed ? ' inspector-collapsed' : ''}`}>
51	      <Titlebar
52	        nav={nav}
53	        onOpenCmdk={() => ws.setCmdk(true)}
54	        onOpenSettings={() => ws.setSettings(true)}
55	        onToggleInspector={ws.toggleInspector}
56	        inspectorCollapsed={ws.inspectorCollapsed}
57	      />
58	
59	      <div className="shell-body">
