/* ---- workspace body (per-phase, scrollable) ---- */
.ws-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 18px 0 32px;
}
.ws-body-inner { animation: bodyIn var(--dur-3) var(--ease-out); }
.body-title {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 12px;
}
