.body-meta { font-family: var(--mono); font-size: 11.5px; color: var(--text-2); }

/* generic bordered surface inside a body */
.surface {
  border: 1px solid var(--hairline);
  border-radius: var(--radius-lg);
  background: var(--panel-2);
  overflow: hidden;
}

/* ============================================================================
   PHASE BODY — grill (ideation / spec)
   ========================================================================== */
.grill { max-width: none; }
.grill-panel {
  border: 1px solid var(--hairline);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--panel-2);
  display: flex;
  flex-direction: column;
}
.grill-strip {
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 12px;
  background: var(--panel);
  border-bottom: 1px solid var(--hairline-soft);
}
.grill-kind {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 8px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent-hi);
  font-family: var(--mono);
  font-size: 10.5px;
}
.grill-sid { font-family: var(--mono); font-size: 11px; color: var(--text-3); }
.grill-strip-spacer { flex: 1; }
/* End-session: quiet but reachable even over a blank/dead terminal. */
.sess-end { color: color-mix(in srgb, var(--danger) 70%, var(--text-2)); }
.sess-end:hover:not(:disabled) {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 55%, var(--hairline));
}
/* IDE-style hero terminal: fills the viewport height left by the chrome
   (titlebar + header + next-step + strip ≈ 330px) instead of a fixed strip. */
.grill-term {
  height: clamp(320px, calc(100dvh - 330px), 1400px);
