/* Convergence control (ADR-0001 §13.6): Converge button + soft fog warning. */
.converge-bar {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--hairline);
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: flex-start;
}
.converge-fog {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--needs);
}
.converge-fog-icon { flex-shrink: 0; }
.converge-fog-text { color: color-mix(in srgb, var(--needs) 82%, var(--text)); }
.converge-btn { min-width: 120px; }
.converge-override { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.converge-blocked { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }

/* ============================================================================
   PHASE BODY — tickets ledger
   ========================================================================== */
.ledger {
  border: 1px solid var(--hairline);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--panel-2);
}
.ledger-row + .ledger-row { border-top: 1px solid var(--hairline-soft); }
.ledger-head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: background var(--dur-1);
}
.ledger-head:hover { background: var(--panel-3); }
.lg-caret {
  color: var(--text-4);
  width: 12px;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  transition: transform var(--dur-2) var(--ease);
}
.ledger-row.is-open .lg-caret { transform: rotate(90deg); }
.lg-seq { color: var(--text-3); font-family: var(--mono); font-size: 11.5px; width: 22px; flex: 0 0 auto; }
.lg-title { flex: 1; min-width: 0; color: var(--text); font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lg-block { font-family: var(--mono); font-size: 10.5px; color: var(--needs); flex: 0 0 auto; }

content.content:
  --mono: "JetBrains Mono Variable", "Cascadia Code", Consolas, ui-monospace, monospace;
  --sans: "Inter Variable", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  /* ---- metrics ---- */
  --radius-sm: 5px;
  --radius: 7px;
  --radius-lg: 10px;
  --radius-pill: 999px;
  --control-h: 28px;
  --sidebar-w: 252px;
  --inspector-w: 300px;
  --content-max: 1060px; /* centered column for document-style phase bodies */

  /* ---- elevation (floating surfaces only — content stays flat) ---- */
  --shadow-menu: 0 8px 28px -10px rgba(0, 0, 0, 0.7), 0 2px 8px -2px rgba(0, 0, 0, 0.5);
  --shadow-overlay: 0 24px 70px -24px rgba(0, 0, 0, 0.85), 0 8px 24px -12px rgba(0, 0, 0, 0.6);

  /* ---- motion ---- */
  --dur-1: 0.12s; /* micro (hover, color) */
  --dur-2: 0.19s; /* small (rows, chips) */
  --dur-3: 0.32s; /* content enter */
  grid-template-rows: 44px 1fr 28px;
}
.shell-body {
  display: grid;
  grid-template-columns: var(--sidebar-w) 1fr var(--inspector-w);
  min-height: 0;
}
.shell.inspector-collapsed .shell-body {
  grid-template-columns: var(--sidebar-w) 1fr;
}

/* ---- titlebar ---- */
.titlebar {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 14px;
  border-bottom: 1px solid var(--hairline);
  background: var(--panel);
  font-size: 13px;
}
}

/* ============================================================================
   WORKSPACE — pipeline-first center
   ========================================================================== */
.workspace {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--bg);
  position: relative;
}
.ws-empty {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--text-3);
}
.ws-empty-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.85;
}
.ws-empty-title { font-size: 14px; font-weight: 500; color: var(--text-2); }
.ws-empty-sub { font-size: 12.5px; color: var(--text-3); max-width: 40ch; text-align: center; }

/* every direct workspace block sits in a centered rail — no more left-hugging
   content with a dead void on the right */
.ws-head,
.nextstep,
.readonly-bar,
.ws-banner,
.ws-body-inner {
  width: 100%;
  max-width: calc(var(--content-max) + 56px);
  margin-left: auto;
  margin-right: auto;
  padding-left: 28px;
  padding-right: 28px;
}

/* ---- workspace header ---- */
.ws-head {
  flex: 0 0 auto;
  padding-top: 18px;
}
.ws-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ws-title { font-size: 17px; font-weight: 600; letter-spacing: -0.01em; color: var(--text); }
.ws-title-spacer { flex: 1; }
.ws-branch {
  display: inline-flex;
  align-items: center;
